class Solution {
public:
    long long maximumScore(vector<int>& nums) {
        int n = nums.size();
        vector<int> suffix(n);
        suffix[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; --i)
            suffix[i] = min(nums[i], suffix[i + 1]);
        long long sum = 0, ans = LLONG_MIN;
        for (int i = 0; i + 1 < n; ++i) {
            sum += nums[i];
            ans = max(ans, sum - suffix[i + 1]);
        }
        return ans;
    }
};
